from pathlib import Path
import json
root=Path(__file__).resolve().parents[2]
# The token matcher compares complete decimal magnitudes. It has no sample
# key, domain, password, local identifier, or archive filename.
tokens={
 'sevenzip-signature':("'37-7A-BC-AF-27-1C'",'Offset-encoded 7z signature comparison literal'),
 'extract-argument-list':("-ArgumentList @('x',",'Offset-encoded extract-command argument list'),
 'https-downloadfile-call':(".DownloadFile('https://",'Offset-encoded HTTPS DownloadFile call syntax'),
 'hidden-window-option':('-WindowStyle Hidden','Offset-encoded hidden-window command option'),
 'password-variable-argument':("('-p'+$",'Offset-encoded variable password argument syntax'),
 'text-file-filter':("-Filter '*.txt'",'Offset-encoded text-file selection syntax'),
 'executable-file-filter':("-Filter '*.exe'",'Offset-encoded executable-file selection syntax'),
 'start-process-command':('Start-Process $','Offset-encoded variable process launch syntax'),
 'environment-path-removal':('Remove-Item -LiteralPath $env:','Offset-encoded environment-path deletion syntax'),
 'showwindow-call':('::ShowWindow($','Offset-encoded ShowWindow call syntax'),
 'movewindow-call':('::MoveWindow($','Offset-encoded MoveWindow call syntax'),
}
header="""# Additive negative-decimal character representations, not execution claims.
# Full magnitudes are compared; the offset, names and endpoints are unpinned.
# Scan from the array head rather than counting individual integer matches:
# the engine caps each YARA pattern at eight matches.
# Supports compact arrays with uniform 4-9 digit magnitudes per token.
# Generated by testdata/offset-archive-review/generate_tokens.py.
defaults:
  platforms: [windows, unix]
  for: [powershell]
  crit: notable
  conf: 0.98
traits:
"""
def number(index):
 return ' + '.join(f'math.to_number(width >= {d}) * (uint8(start+({index})*stride+width+1-{d})-48)*{10**(d-1)}' for d in range(1,10))
body=[]
for name,(token,desc) in tokens.items():
 deltas=' or\n                    '.join(f'(j == {j} and base - value == {ord(c)-ord(token[0])})' for j,c in enumerate(token) if j)
 source=fr"""import "math"
rule negative_offset_{name.replace('-','_')} {{
  strings:
    $array = /@\(-[0-9]{{4,9}},/
  condition:
    filesize <= 256KB and
    for any a in (1..#array) : (
      @array[a] >= 9 and
      with width = !array[a]-4, start = @array[a]+2 : (
        with stride = width+2 : (
          for any n in (0..(filesize-start)\stride-{len(token)}) : (
            uint8(start+n*stride) == 45 and
            (uint8(start+(n+{len(token)-1})*stride+width+1) == 44 or
             uint8(start+(n+{len(token)-1})*stride+width+1) == 41) and
            for all d in (1..width) : (
              uint8(start+n*stride+d) >= 48 and
              uint8(start+n*stride+d) <= 57
            ) and
            with base = {number('n')} : (
              for all j in (1..{len(token)-1}) : (
                uint8(start+(n+j)*stride) == 45 and
                uint8(start+(n+j)*stride-1) == 44 and
                for all d in (1..width) : (
                  uint8(start+(n+j)*stride+d) >= 48 and
                  uint8(start+(n+j)*stride+d) <= 57
                ) and
                with value = {number('n+j')} : (
                  {deltas}
                )
              )
            )
          )
        )
      )
    )
}}"""
 body.append(f'  - id: negative-offset-{name}\n    desc: {desc}\n    size_max: 262144\n    if:\n      type: yara\n      source: |\n'+''.join('        '+line+'\n' for line in source.splitlines()))
(root/'metadata/lang/encoding/powershell-offset-call-tokens.yaml').write_text(header+'\n'.join(body))
(root/'testdata/offset-archive-review').mkdir(exist_ok=True)
(root/'testdata/offset-archive-review/tokens.json').write_text(json.dumps({k:v[0] for k,v in tokens.items()},indent=2)+'\n')
